  border-color: var(--line-strong);
  background: transparent;
  color: var(--text);
}

.button--secondary:hover:not(:disabled) {
  border-color: var(--cyan-deep);
  background: rgba(67, 215, 231, 0.06);
}

.button--danger {
  border-color: rgba(255, 125, 130, 0.5);
  background: rgba(255, 125, 130, 0.1);
  color: #ffc6c8;
}

.button--danger:hover:not(:disabled) {
  background: rgba(255, 125, 130, 0.16);
}

.button-arrow {
  font-family: Arial, sans-serif;
  font-size: 1.2em;
  line-height: 1;
}

.button[data-mode="login"]::after {
  font-family: Arial, sans-serif;
  font-size: 1.2em;
  line-height: 1;
  content: "→";
}

button:disabled {
  border-color: #263a44;
  background: #15232b;
  color: #78919b;
  cursor: not-allowed;
  opacity: 1;
}

.auth-footer {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  margin-top: 14px;
}

.message {
  min-width: 0;
  min-height: 1.5em;
  margin: 0;
  color: var(--muted-strong);
  font-size: 0.8rem;
  line-height: 1.45;
}

.claim-form {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 10px;
  margin-top: 22px;
}

.button--claim {
  min-height: 46px;
}

.message--claim {
  margin-top: 10px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(67, 215, 231, 0.04);
}

.message--claim:empty {
  display: none;
}

.message--claim[data-state="pending"] {
  border-color: rgba(244, 201, 107, 0.34);
  color: var(--amber);
}

.message--claim[data-state="success"] {
  border-color: rgba(98, 221, 167, 0.34);
  color: var(--green);
}

.message--claim[data-state="error"] {
  border-color: rgba(255, 125, 130, 0.4);
  color: var(--red);
}

.locker-selector {
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.locker-hint {
  margin-top: 7px;
}

.status-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.freshness-key {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.68rem;
  white-space: nowrap;
}

.freshness-key span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 0 4px rgba(67, 215, 231, 0.08);
}

.status-rail {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-md);
  background: var(--line);
}

.status-cell {
  display: grid;
  min-width: 0;
  min-height: 134px;
  grid-template-rows: auto auto 1fr;
  gap: 7px;
  padding: 15px;
  background: rgba(6, 17, 24, 0.94);
}

.status-cell-top {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.signal-bars {
  width: 18px;
  height: 10px;
  opacity: 0.7;
  background:
    linear-gradient(to top, var(--cyan-deep) 42%, transparent 42%) 0 0 / 3px 100% no-repeat,
    linear-gradient(to top, var(--cyan-deep) 68%, transparent 68%) 7px 0 / 3px 100% no-repeat,
    linear-gradient(to top, var(--cyan-deep) 100%, transparent 100%) 14px 0 / 3px 100% no-repeat;
}

.status-cell .status-label {
  align-self: end;
  color: var(--muted);
}

.status-cell strong {
  min-width: 0;
  align-self: start;
  color: var(--text);
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: clamp(0.86rem, 1.3vw, 1rem);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.status-cell--lock strong {
  color: var(--amber);
}

.status-cell--alarm strong {
  color: var(--red);
}

.status-cell--led strong {
  color: var(--green);
}

.status-meta-grid {
  display: grid;
  grid-template-columns: minmax(200px, 0.35fr) minmax(0, 0.65fr);
  gap: 10px;
  margin-top: 10px;
}

.status-meta {
  display: grid;
  min-width: 0;
  gap: 5px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(6, 17, 24, 0.56);
}

.status-meta strong {
  min-width: 0;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 0.78rem;
  font-weight: 650;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.status-meta--alert strong {
  color: var(--amber);
}

.message--state,
.message--command {
  position: relative;
  margin-top: 12px;
  padding: 11px 13px 11px 36px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(67, 215, 231, 0.045);
}

.message--state::before,
.message--command::before {
  position: absolute;
  top: 14px;
  left: 14px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--cyan-deep);
  border-radius: 50%;
  content: "";
}

.controls {
  display: grid;
  gap: 17px;
  margin-top: 22px;
}

.control-group {
  min-width: 0;
}

.control-group-label {
  display: block;
  margin-bottom: 7px;
}

.control-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.control-button {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 66px;
  justify-items: start;
  align-content: center;
  gap: 4px;
  padding: 11px 13px;
  overflow: hidden;
  border: 1px solid rgba(98, 221, 167, 0.32);
  border-radius: 11px;
  background: rgba(98, 221, 167, 0.08);
  color: #dffbec;
  cursor: pointer;
  font-weight: 730;
  text-align: left;
  transition: border-color 150ms ease, background-color 150ms ease, transform 150ms ease;
}

.control-button--open {
  border-color: var(--line-strong);
  background: transparent;
  color: var(--text);
}

.control-button--alarm {
  border-color: rgba(255, 125, 130, 0.42);
  background: rgba(255, 125, 130, 0.1);
  color: #ffd1d3;
}

.control-button--alarm .control-code {
  color: var(--red);
}

.control-button:hover:not(:disabled) {
  border-color: var(--green);
  background: rgba(98, 221, 167, 0.13);
  transform: translateY(-1px);
}

.control-button .control-code {
  color: var(--green);
  font-size: 0.62rem;
}

.control-button:disabled .control-code {
  color: #78919b;
}

.control-button[data-pending="true"] {
  border-color: rgba(244, 201, 107, 0.6);
  background: rgba(244, 201, 107, 0.09);
  color: #ffe6a9;
  cursor: progress;
}

.control-button[data-pending="true"]::after {
  position: absolute;
  top: 11px;
  right: 11px;
  width: 12px;
  height: 12px;
  border: 2px solid rgba(244, 201, 107, 0.24);
  border-top-color: var(--amber);
  border-radius: 50%;
  content: "";
  animation: spin 750ms linear infinite;
}

.chat-form {
  position: relative;
  display: grid;
  gap: 10px;
  margin-top: 22px;
}

form[data-pending="true"] {
  cursor: progress;
}

form[data-pending="true"] input,
form[data-pending="true"] textarea,
form[data-pending="true"] button {
  opacity: 0.68;
  pointer-events: none;
}

form[data-pending="true"]::after {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  width: 15px;
  height: 15px;
  border: 2px solid rgba(244, 201, 107, 0.26);
  border-top-color: var(--amber);
  border-radius: 50%;
  content: "";
  animation: spin 750ms linear infinite;
}

.chat-submit {
  justify-self: start;
}

.answer-shell {
  min-width: 0;
  margin-top: 16px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: rgba(4, 13, 19, 0.72);
}

#answer {
  min-width: 0;
  min-height: 80px;
  margin: 8px 0 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted-strong);
  font-family: inherit;
  font-size: 0.86rem;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.phase3-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  margin-top: 18px;
}

.data-card,
.settings-card {
  padding: 25px;
}

.settings-card {
  grid-column: 1 / -1;
}

.data-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 20px;
}

.field--compact {
  width: min(180px, 100%);
}

.history-list {
  min-height: 250px;
  max-height: 390px;
  margin: 16px 0 10px;
  padding: 14px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: rgba(4, 13, 19, 0.72);
  color: var(--muted-strong);
  font: 0.77rem/1.65 "SFMono-Regular", Consolas, monospace;
  white-space: pre-wrap;
}

.chart-summary {
  margin: 20px 0 12px;
  color: var(--muted-strong);
  font-size: 0.84rem;
}

.chart-bars {
  display: flex;
  min-height: 250px;
  align-items: end;
  gap: 6px;
  padding: 16px 10px 8px;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: rgba(4, 13, 19, 0.72);
}

.chart-day {
  display: grid;
  min-width: 30px;
  height: 220px;
  flex: 1 0 30px;
  grid-template-columns: repeat(2, minmax(8px, 1fr));
  align-items: end;
  gap: 3px;
}

.chart-bar {
  min-height: 2px;
  border-radius: 4px 4px 1px 1px;
}

.chart-bar--open { background: var(--cyan); }
.chart-bar--alert { background: var(--red); }

.chart-label {
  grid-column: 1 / -1;
  color: var(--muted);
  font: 0.58rem/1.2 "SFMono-Regular", Consolas, monospace;
  text-align: center;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 10px;
  color: var(--muted);
  font-size: 0.75rem;
}

.chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.chart-legend i {
  width: 9px;
  height: 9px;
  border-radius: 2px;
}

.legend-open { background: var(--cyan); }
.legend-alert { background: var(--red); }

.settings-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 20px;
}

.check-field {
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  gap: 10px;
  color: var(--muted-strong);
  font-weight: 700;
}

.check-field input {
  width: 18px;
  min-height: 18px;
  accent-color: var(--cyan);
}

.settings-actions {
  display: flex;
  grid-column: 1 / -1;
  flex-wrap: wrap;
  gap: 10px;
}

.page-footer {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 4px 0;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.66rem;
}

.page-footer p {
  margin: 0;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 960px) {
  .identity-grid,
  .action-grid,
  .phase3-grid {
    grid-template-columns: 1fr;
  }

  .status-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .settings-card {
    grid-column: auto;
  }
}

@media (max-width: 720px) {
  .app-shell {
    width: min(100% - 24px, 1180px);
    padding-top: 18px;
  }

  .topbar {
    display: grid;
    gap: 15px;
    padding-bottom: 17px;
  }

  .session-panel {
    width: 100%;
  }

  .auth-card,
  .ownership-card,
  .control-card,
  .chat-card,
  .data-card,
  .settings-card,
  .status-console {
    padding: 19px;
    border-radius: 18px;
  }

  .form-stack {
    grid-template-columns: 1fr;
  }

  .form-stack .field:first-child,
  .auth-actions {
    grid-column: auto;
  }

  .status-header {
    display: grid;
  }

  .freshness-key {
    justify-self: start;
  }

  .status-meta-grid {
    grid-template-columns: 1fr;
  }

  .settings-form {
    grid-template-columns: 1fr;
  }

  .data-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .field--compact {
    width: 100%;
  }

  .page-footer {
    display: grid;
  }
}

@media (max-width: 460px) {
  .brand-mark {
    width: 48px;
    height: 55px;
  }

  .brand-mark span {
    bottom: 12px;
  }

  .session-panel {
    grid-template-columns: auto minmax(0, 1fr);
    border-radius: 14px;
  }

  .phase-badge {
    grid-column: 2;
    justify-self: start;
  }

  .section-heading {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 10px;
  }

  .section-index {
    width: 30px;
    height: 30px;
  }

  .auth-actions,
  .auth-footer,
  .claim-form,
  .settings-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .auth-actions .button,
  .auth-footer .button,
  .button--claim,
  .chat-submit {
    width: 100%;
  }

  .status-rail {
    grid-template-columns: 1fr;
  }

  .status-cell {
    min-height: 116px;
  }

  .control-buttons {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

