          <span class="micro-label">Phiên bảo mật</span>
          <p id="session-label" role="status" aria-live="polite">Chưa đăng nhập</p>
        </div>
        <span class="phase-badge">Phase 3</span>
      </div>
    </header>

    <div class="identity-grid">
      <section id="auth-card" class="card auth-card" aria-labelledby="auth-title">
        <div class="section-heading">
          <span class="section-index" aria-hidden="true">01</span>
          <div>
            <p class="section-kicker">Identity perimeter</p>
            <h2 id="auth-title">Tài khoản</h2>
            <p class="section-copy">Đăng nhập bằng Supabase để mọi yêu cầu bảo vệ mang Bearer token của chính bạn.</p>
          </div>
        </div>

        <form id="auth-form" class="form-stack" data-pending="false" aria-busy="false">
          <label class="field" for="full-name">
            <span class="field-label">Họ và tên</span>
            <span class="field-hint">Chỉ bắt buộc khi đăng ký tài khoản mới.</span>
            <input id="full-name" type="text" autocomplete="name" maxlength="120" placeholder="Nguyễn Văn A">
