          <label class="field" for="email">
            <span class="field-label">Email test</span>
            <input id="email" type="email" autocomplete="username" inputmode="email" placeholder="name@example.com" required>
          </label>

          <label class="field" for="password">
            <span class="field-label">Mật khẩu</span>
            <input id="password" type="password" autocomplete="current-password" minlength="8" placeholder="Tối thiểu 8 ký tự" required>
          </label>

          <div class="auth-actions">
            <button type="submit" data-mode="login" class="button button--primary">Đăng nhập</button>
            <button type="submit" data-mode="register" class="button button--secondary">Đăng ký</button>
          </div>
        </form>

        <div class="auth-footer">
          <button id="logout" type="button" class="button button--danger" hidden>Đăng xuất an toàn</button>
          <p id="auth-message" class="message" role="status" aria-live="polite" aria-atomic="true"></p>
        </div>
      </section>

      <section class="card ownership-card" aria-labelledby="ownership-title">
