            <input id="locker-code" value="LOCKER-001" autocomplete="off" autocapitalize="characters" spellcheck="false">
          </label>
          <button id="claim-button" type="submit" class="button button--claim">Claim một lần</button>
        </form>
        <p id="claim-message" class="message message--claim" data-state="idle" role="status" aria-live="polite" aria-atomic="true"></p>

        <div class="locker-selector">
