          <strong id="device">OFFLINE</strong>
        </article>
        <article class="status-cell status-cell--door">
          <div class="status-cell-top"><span class="status-code">SNS·03</span><span class="signal-bars" aria-hidden="true"></span></div>
          <span class="status-label">Cửa</span>
          <strong id="door">UNKNOWN</strong>
        </article>
        <article class="status-cell status-cell--lock">
          <div class="status-cell-top"><span class="status-code">SEC·04</span><span class="signal-bars" aria-hidden="true"></span></div>
          <span class="status-label">Khóa</span>
          <strong id="lock">UNKNOWN — chưa xác nhận</strong>
        </article>
        <article class="status-cell status-cell--alarm">
          <div class="status-cell-top"><span class="status-code">ALM·05</span><span class="signal-bars" aria-hidden="true"></span></div>
          <span class="status-label">Còi báo động</span>
          <strong id="alarm">INACTIVE</strong>
