            <span class="field-label">Múi giờ</span>
            <input id="report-timezone" value="Asia/Ho_Chi_Minh" autocomplete="off">
          </label>
          <div class="settings-actions">
            <button id="load-settings" type="button" class="button button--secondary">Tải cài đặt</button>
            <button id="save-settings" type="submit" class="button button--primary">Lưu cài đặt</button>
